package com.henson.jarvis.phone;
import android.net.Uri;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.json.*;import java.net.*;import java.security.*;import java.security.interfaces.RSAPublicKey;import java.util.*;import java.nio.charset.StandardCharsets;
@RunWith(AndroidJUnit4.class)
public class SignInRecoveryTest {
 private TokenVault vault;private OpenAIClient ai;private Fake network;private Uri auth,callback;private JSONObject tokens,keys;
 private static String b64(byte[] value){return Base64.getUrlEncoder().withoutPadding().encodeToString(value);}
 @Before public void setup()throws Exception{vault=new TokenVault(InstrumentationRegistry.getInstrumentation().getTargetContext());vault.write(new JSONObject().put("accounts",new JSONObject()));network=new Fake();ai=new OpenAIClient(vault,network);auth=Uri.parse(ai.authorize(null,"http://127.0.0.1:1455/auth/callback"));callback=Uri.parse("http://127.0.0.1:1455/auth/callback?code=test-code&client_id=oaiapp_fixture&state="+auth.getQueryParameter("state"));
  KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);KeyPair pair=generator.generateKeyPair();RSAPublicKey pub=(RSAPublicKey)pair.getPublic();keys=new JSONObject().put("keys",new JSONArray().put(new JSONObject().put("kty","RSA").put("kid","fixture").put("n",b64(pub.getModulus().toByteArray())).put("e",b64(pub.getPublicExponent().toByteArray()))));JSONObject claims=new JSONObject().put("iss","https://auth.openai.com").put("aud","oaiapp_fixture").put("sub","fixture-user").put("nonce",auth.getQueryParameter("nonce")).put("exp",System.currentTimeMillis()/1000+600);String data=b64(new JSONObject().put("alg","RS256").put("kid","fixture").toString().getBytes(StandardCharsets.UTF_8))+"."+b64(claims.toString().getBytes(StandardCharsets.UTF_8));Signature signer=Signature.getInstance("SHA256withRSA");signer.initSign(pair.getPrivate());signer.update(data.getBytes(StandardCharsets.US_ASCII));String id=data+"."+b64(signer.sign());tokens=new JSONObject().put("scope","resource.invoke chatgpt.tokens.use.direct offline_access openid email profile").put("id_token",id).put("access_token","fixture-access-secret").put("refresh_token","fixture-refresh-secret").put("expires_in",3600);
 }
 @After public void clear()throws Exception{vault.write(new JSONObject().put("accounts",new JSONObject()));}
 private final class Fake implements OpenAIClient.Transport{int tokenCalls,keyCalls;boolean failToken,failKey;public JSONObject request(String url,String method,String bearer,String body,boolean form)throws Exception{if(url.endsWith("oauth/token")){tokenCalls++;if(failToken){failToken=false;throw new UnknownHostException("simulated DNS failure");}return tokens;}if(url.endsWith("jwks.json")){keyCalls++;if(failKey){failKey=false;throw new UnknownHostException("simulated key lookup failure");}return keys;}throw new Exception("Unexpected endpoint in test");}}
 @Test public void callbackStagingMakesNoNetworkRequest()throws Exception{ai.stageCallback(callback);assertTrue(ai.hasStagedCallback());assertFalse(ai.status().getBoolean("connected"));assertTrue(ai.status().getBoolean("canRetry"));assertEquals(0,network.tokenCalls);assertEquals(0,network.keyCalls);}
 @Test public void dnsFailureRetainsCodeAndKeyFailureDoesNotRedeemCodeTwice()throws Exception{ai.stageCallback(callback);network.failToken=true;network.failKey=true;try{ai.finishAuthorization();fail("Expected token DNS failure");}catch(Exception expected){}assertTrue(ai.hasStagedCallback());assertEquals(1,network.tokenCalls);try{ai.finishAuthorization();fail("Expected key DNS failure");}catch(Exception expected){}assertEquals(2,network.tokenCalls);assertEquals(1,network.keyCalls);ai.finishAuthorization();assertEquals(2,network.tokenCalls);assertEquals(2,network.keyCalls);assertTrue(ai.status().getBoolean("connected"));assertFalse(ai.hasStagedCallback());assertFalse(ai.status().toString().contains("fixture-access-secret"));}
 @Test public void freshSignInReusesIssuedRegistrationAndFreshState()throws Exception{ai.stageCallback(callback);Uri again=Uri.parse(ai.authorize(null,"http://127.0.0.1:1455/auth/callback"));assertEquals("oaiapp_fixture",again.getQueryParameter("client_id"));assertNull(again.getQueryParameter("agent_name_hint"));assertNotEquals(auth.getQueryParameter("state"),again.getQueryParameter("state"));assertNotEquals(auth.getQueryParameter("nonce"),again.getQueryParameter("nonce"));try{ai.stageCallback(callback);fail("Old state accepted");}catch(Exception expected){}assertEquals(0,network.tokenCalls);}
 @Test public void retriesOnlyDnsFailuresAndNeverAmbiguousTimeouts()throws Exception{int[] calls={0},pauses={0};int value=DnsRetry.run(()->{if(++calls[0]<3)throw new UnknownHostException("fixture");return 42;},ms->pauses[0]++);assertEquals(42,value);assertEquals(3,calls[0]);assertEquals(2,pauses[0]);calls[0]=0;try{DnsRetry.run(()->{calls[0]++;throw new SocketTimeoutException("ambiguous response");},ms->fail("Timeout must not replay POST"));fail("Expected timeout");}catch(SocketTimeoutException expected){}assertEquals(1,calls[0]);}
}
